pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _runTest(uint256 depositAmount, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > collectAmount);
        vm.assume(address(this).balance >= depositAmount);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        try c.Collect(collectAmount) {} catch { return; }
        assertTrue(c.balances(address(this)) == depositAmount - collectAmount);
    }

    function testFuzz_runTest(uint256 depositAmount, uint256 collectAmount) public {
        _runTest(depositAmount, collectAmount);
    }

    receive() external payable {}
}
